window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b881cf25523b8778"]={"versions": [{"id": "FIG-b881cf25523b8778", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt der AUTOSAR-Metamodellebene M2).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Definition der Metaklasse <code>MultidimensionalTime</code> im Rahmen des <em>Generic Structure Template</em> (<code>AUTOSAR_FO_TPS_GenericStructureTemplate</code>). Das Element dient der standardisierten Beschreibung von Zeit- und Rasterinformationen, die nicht ausschließlich auf der skalaren physikalischen SI-Basiseinheit Sekunde beruhen. Es bildet die formale Metamodell-Brücke zur Abbildung von ereignis-, winkel- und zyklussynchronen Zeiträumen (z. B. Kurbelwellenwinkel °CA in Verbrennungsmotoren, Segmentzeiten, Zählerzyklen) für die Interoperabilität mit Mess-, Kalibrier- und Diagnosesystemen gemäß ASAM MCD-2 MC (A2L) / ASAP2 sowie MSR-Standards.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Metaklasse:</strong></li>\n<li><code>MultidimensionalTime</code>: Struktur-Element ohne explizite Stereotypisierung im Ausschnitt.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ cseCode: CseCodeType [0..1]</code>: Optionales Attribut (Kardinalität <code>0..1</code>). Spezifiziert die Basisdomäne des Takts bzw. Synchronisationsereignisses (<em>Clock / Cycle Synchronous Event Code</em> nach ASAM MCD-2 MC, z. B. zeitbasiert, winkelbasiert, ereignisbasiert).</li>\n<li><code>+ cseCodeFactor: Integer [0..1]</code>: Optionaler ganzzahliger Multiplikationsfaktor (Kardinalität <code>0..1</code>). Skaliert die Raster-Einheit relativ zu dem durch <code>cseCode</code> festgelegten Basis-Event.</li>\n<li><strong>Beziehungen & Vererbung:</strong></li>\n<li>Das Diagramm stellt ein isoliertes Metaklassen-Element dar (keine Sub- oder Superklassen abgebildet).</li>\n<li>Im Gesamt-Metamodell fungiert <code>MultidimensionalTime</code> als aggregierter Typ in Timing-, Measurement- und Calibration-Strukturen (z. B. zur Deklaration von Abtastraten oder Ausführungsintervallen von Software-Komponenten und Messgrößen).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Charakter:</strong> Da es sich um ein statisches Entwurfs- und Beschreibungsartefakt (M2-Ebene) handelt, existiert zur Target-Laufzeit kein dynamischer Programmablauf, Zustandsautomat oder Callback-Mechanismus (weder Det noch Dem involviert).</li>\n<li><strong>Auswertungsdynamik in der Toolchain:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>ARXML-Import:</strong> Autorisierte Generatoren werten <code>cseCode</code> und <code>cseCodeFactor</code> aus.</li>\n<li><strong>Raster-Zuordnung:</strong> Falls <code>cseCode</code> gesetzt ist, wird das betreffende Software-Element (z. B. Runnable, Messkanal) nicht in ein rein chronometrisches OS-Task-Raster (z. B. 10 ms), sondern in ein ereignis-/winkelsynchrones Task- bzw. Messraster überführt.</li>\n<li><strong>A2L-Generierung:</strong> Automatische Transformation der Attribute in die korrespondierenden A2L-Tags <code>CSE_CODE</code> und <code>CSE_CODE_FACTOR</code>.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Anforderungen (SWS-Bezug):</strong></li>\n<li><code>TPS_GST_00224</code>: Spezifiziert die Semantik der Metaklasse <code>MultidimensionalTime</code> zur Entkopplung von rein physikalischen Zeitangaben hin zu dimensionsbehafteten Ereignissen.</li>\n<li><code>TPS_GST_00354</code>: Definiert die funktionale Abhängigkeit der Attribute: Wird <code>cseCodeFactor</code> spezifiziert, ist das Vorhandensein von <code>cseCode</code> obligatorisch, um undefinierte Basis-Dimensionen zu verhindern.</li>\n<li><code>TPS_GST_00358</code>: Regelt die Wertebereichsbeschränkungen und das semantische Mapping auf ASAM MCD-2 MC-Kompatibilität (<code>CSE_CODE</code>-Wertemenge).</li>\n<li><strong>Konsequenzen für Embedded- und Toolchain-Entwickler:</strong></li>\n<li><strong>BSW & RTE:</strong> Keine direkten C-API-Änderungen (<code>Rte_Read</code>/<code>Rte_Write</code> bleiben unberührt). Auf BSWM/OS-Ebene markiert dies Runnables, die typischerweise an Interrupts/Complex Device Driver (CDD, z. B. Winkeltaktgeber, Injektionssteuerung) gebunden sind statt an den System-Timer.</li>\n<li><strong>A2L-/MCD-Toolchain:</strong> Generator-Entwickler müssen sicherstellen, dass ARXML-Beschreibungen mit instanziiertem <code>MultidimensionalTime</code> syntaktisch valide A2L-Einträge erzeugen, damit Kalibriertools (z. B. CANape, INCA) das korrekte Trigger-Raster für DAQ-Listen und ODTs konfigurieren.</li>\n</ul>"}, {"id": "FIG-ea631ae8bc6ec74e", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm (Ausschnitt der AUTOSAR-Metamodellebene M2).</li>\n<li><strong>Technischer Zweck & Einordnung:</strong> Definition der Metaklasse <code>MultidimensionalTime</code> im Rahmen des <em>Generic Structure Template</em> (<code>AUTOSAR_FO_TPS_GenericStructureTemplate</code>). Das Element dient der standardisierten Beschreibung von Zeit- und Rasterinformationen, die nicht ausschließlich auf der skalaren physikalischen SI-Basiseinheit Sekunde beruhen. Es bildet die formale Metamodell-Brücke zur Abbildung von ereignis-, winkel- und zyklussynchronen Zeiträumen (z. B. Kurbelwellenwinkel °CA in Verbrennungsmotoren, Segmentzeiten, Zählerzyklen) für die Interoperabilität mit Mess-, Kalibrier- und Diagnosesystemen gemäß ASAM MCD-2 MC (A2L) / ASAP2 sowie MSR-Standards.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Metaklasse:</strong></li>\n<li><code>MultidimensionalTime</code>: Struktur-Element ohne explizite Stereotypisierung im Ausschnitt.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ cseCode: CseCodeType [0..1]</code>: Optionales Attribut (Kardinalität <code>0..1</code>). Spezifiziert die Basisdomäne des Takts bzw. Synchronisationsereignisses (<em>Clock / Cycle Synchronous Event Code</em> nach ASAM MCD-2 MC, z. B. zeitbasiert, winkelbasiert, ereignisbasiert).</li>\n<li><code>+ cseCodeFactor: Integer [0..1]</code>: Optionaler ganzzahliger Multiplikationsfaktor (Kardinalität <code>0..1</code>). Skaliert die Raster-Einheit relativ zu dem durch <code>cseCode</code> festgelegten Basis-Event.</li>\n<li><strong>Beziehungen & Vererbung:</strong></li>\n<li>Das Diagramm stellt ein isoliertes Metaklassen-Element dar (keine Sub- oder Superklassen abgebildet).</li>\n<li>Im Gesamt-Metamodell fungiert <code>MultidimensionalTime</code> als aggregierter Typ in Timing-, Measurement- und Calibration-Strukturen (z. B. zur Deklaration von Abtastraten oder Ausführungsintervallen von Software-Komponenten und Messgrößen).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Charakter:</strong> Da es sich um ein statisches Entwurfs- und Beschreibungsartefakt (M2-Ebene) handelt, existiert zur Target-Laufzeit kein dynamischer Programmablauf, Zustandsautomat oder Callback-Mechanismus (weder Det noch Dem involviert).</li>\n<li><strong>Auswertungsdynamik in der Toolchain:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>ARXML-Import:</strong> Autorisierte Generatoren werten <code>cseCode</code> und <code>cseCodeFactor</code> aus.</li>\n<li><strong>Raster-Zuordnung:</strong> Falls <code>cseCode</code> gesetzt ist, wird das betreffende Software-Element (z. B. Runnable, Messkanal) nicht in ein rein chronometrisches OS-Task-Raster (z. B. 10 ms), sondern in ein ereignis-/winkelsynchrones Task- bzw. Messraster überführt.</li>\n<li><strong>A2L-Generierung:</strong> Automatische Transformation der Attribute in die korrespondierenden A2L-Tags <code>CSE_CODE</code> und <code>CSE_CODE_FACTOR</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Normative Anforderungen (SWS-Bezug):</strong></li>\n<li><code>TPS_GST_00224</code>: Spezifiziert die Semantik der Metaklasse <code>MultidimensionalTime</code> zur Entkopplung von rein physikalischen Zeitangaben hin zu dimensionsbehafteten Ereignissen.</li>\n<li><code>TPS_GST_00354</code>: Definiert die funktionale Abhängigkeit der Attribute: Wird <code>cseCodeFactor</code> spezifiziert, ist das Vorhandensein von <code>cseCode</code> obligatorisch, um undefinierte Basis-Dimensionen zu verhindern.</li>\n<li><code>TPS_GST_00358</code>: Regelt die Wertebereichsbeschränkungen und das semantische Mapping auf ASAM MCD-2 MC-Kompatibilität (<code>CSE_CODE</code>-Wertemenge).</li>\n<li><strong>Konsequenzen für Embedded- und Toolchain-Entwickler:</strong></li>\n<li><strong>BSW & RTE:</strong> Keine direkten C-API-Änderungen (<code>Rte_Read</code>/<code>Rte_Write</code> bleiben unberührt). Auf BSWM/OS-Ebene markiert dies Runnables, die typischerweise an Interrupts/Complex Device Driver (CDD, z. B. Winkeltaktgeber, Injektionssteuerung) gebunden sind statt an den System-Timer.</li>\n<li><strong>A2L-/MCD-Toolchain:</strong> Generator-Entwickler müssen sicherstellen, dass ARXML-Beschreibungen mit instanziiertem <code>MultidimensionalTime</code> syntaktisch valide A2L-Einträge erzeugen, damit Kalibriertools (z. B. CANape, INCA) das korrekte Trigger-Raster für DAQ-Listen und ODTs konfigurieren.</li>\n</ul>"}], "trans": [{"from": "FIG-b881cf25523b8778", "to": "FIG-ea631ae8bc6ec74e", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
